PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS cities(id TEXT PRIMARY KEY,names TEXT NOT NULL,timezone TEXT NOT NULL DEFAULT 'Asia/Tbilisi',currency TEXT NOT NULL DEFAULT 'GEL',active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)));
CREATE TABLE IF NOT EXISTS vendors(id TEXT PRIMARY KEY,city_id TEXT NOT NULL REFERENCES cities(id),slug TEXT NOT NULL UNIQUE,names TEXT NOT NULL,description TEXT NOT NULL DEFAULT '{}',address TEXT NOT NULL DEFAULT '',phone TEXT NOT NULL DEFAULT '',active INTEGER NOT NULL DEFAULT 0 CHECK(active IN(0,1)),demo INTEGER NOT NULL DEFAULT 1,delivery_fee INTEGER NOT NULL DEFAULT 0 CHECK(delivery_fee>=0),delivery_enabled INTEGER NOT NULL DEFAULT 0,lead_minutes INTEGER NOT NULL DEFAULT 30 CHECK(lead_minutes>=0),open_minute INTEGER NOT NULL DEFAULT 540,close_minute INTEGER NOT NULL DEFAULT 1200,slot_capacity INTEGER NOT NULL DEFAULT 8 CHECK(slot_capacity>0),CHECK(open_minute<close_minute));
CREATE INDEX IF NOT EXISTS vendor_city ON vendors(city_id,active);
CREATE TABLE IF NOT EXISTS products(id TEXT PRIMARY KEY,vendor_id TEXT NOT NULL REFERENCES vendors(id),source_id TEXT,names TEXT NOT NULL,description TEXT NOT NULL DEFAULT '{}',category TEXT NOT NULL,image TEXT NOT NULL,price INTEGER NOT NULL CHECK(price>=0),stock INTEGER NOT NULL DEFAULT 0 CHECK(stock>=0),reserved INTEGER NOT NULL DEFAULT 0 CHECK(reserved>=0 AND reserved<=stock),active INTEGER NOT NULL DEFAULT 1,lead_minutes INTEGER NOT NULL DEFAULT 30,options TEXT NOT NULL DEFAULT '[]',allergens TEXT NOT NULL DEFAULT '[]',cost INTEGER CHECK(cost>=0),version INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS product_vendor ON products(vendor_id,active);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,name TEXT NOT NULL,hash TEXT NOT NULL,salt TEXT NOT NULL,owner INTEGER NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS memberships(user_id TEXT NOT NULL REFERENCES users(id),vendor_id TEXT NOT NULL REFERENCES vendors(id),role TEXT NOT NULL CHECK(role IN('ADMIN','STAFF','DRIVER')),PRIMARY KEY(user_id,vendor_id));
CREATE TABLE IF NOT EXISTS sessions(hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS invites(hash TEXT PRIMARY KEY,vendor_id TEXT NOT NULL REFERENCES vendors(id),role TEXT NOT NULL CHECK(role IN('ADMIN','STAFF','DRIVER')),expires INTEGER NOT NULL,used INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS auth_limits(key TEXT PRIMARY KEY,attempts INTEGER NOT NULL DEFAULT 0,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS slots(vendor_id TEXT NOT NULL REFERENCES vendors(id),day TEXT NOT NULL,minute INTEGER NOT NULL,capacity INTEGER NOT NULL CHECK(capacity>0),reserved INTEGER NOT NULL DEFAULT 0 CHECK(reserved>=0 AND reserved<=capacity),PRIMARY KEY(vendor_id,day,minute));
CREATE TABLE IF NOT EXISTS orders(id TEXT PRIMARY KEY,vendor_id TEXT NOT NULL REFERENCES vendors(id),city_id TEXT NOT NULL REFERENCES cities(id),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'NEW',payment TEXT NOT NULL DEFAULT 'UNPAID',method TEXT NOT NULL CHECK(method IN('cash','transfer')),fulfillment TEXT NOT NULL CHECK(fulfillment IN('pickup','delivery')),day TEXT NOT NULL,minute INTEGER NOT NULL,currency TEXT NOT NULL,items_total INTEGER NOT NULL CHECK(items_total>=0),delivery_fee INTEGER NOT NULL CHECK(delivery_fee>=0),total INTEGER NOT NULL CHECK(total>=0),paid INTEGER NOT NULL DEFAULT 0 CHECK(paid>=0),version INTEGER NOT NULL DEFAULT 0,customer TEXT NOT NULL,key_hash TEXT NOT NULL,idem TEXT NOT NULL UNIQUE,fingerprint TEXT NOT NULL,driver_id TEXT REFERENCES users(id),original_items TEXT NOT NULL,proposal TEXT,previous_status TEXT,UNIQUE(id,vendor_id),FOREIGN KEY(vendor_id,day,minute) REFERENCES slots(vendor_id,day,minute));
CREATE INDEX IF NOT EXISTS order_vendor_status ON orders(vendor_id,status,created_at);
CREATE TABLE IF NOT EXISTS order_items(order_id TEXT NOT NULL,vendor_id TEXT NOT NULL,product_id TEXT NOT NULL REFERENCES products(id),title TEXT NOT NULL,qty INTEGER NOT NULL CHECK(qty>0 AND qty<=100),price INTEGER NOT NULL CHECK(price>=0),cost INTEGER,options TEXT NOT NULL DEFAULT '[]',note TEXT NOT NULL DEFAULT '',PRIMARY KEY(order_id,product_id,options,note),FOREIGN KEY(order_id,vendor_id) REFERENCES orders(id,vendor_id));
CREATE TABLE IF NOT EXISTS order_events(id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id),at TEXT NOT NULL,actor TEXT NOT NULL,event TEXT NOT NULL,data TEXT NOT NULL DEFAULT '{}');
CREATE INDEX IF NOT EXISTS events_order ON order_events(order_id,at);
CREATE TABLE IF NOT EXISTS payments(id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id),at TEXT NOT NULL,actor TEXT NOT NULL REFERENCES users(id),amount INTEGER NOT NULL CHECK(amount>0),currency TEXT NOT NULL,reason TEXT NOT NULL,command TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS commands(id TEXT PRIMARY KEY,actor TEXT NOT NULL,fingerprint TEXT NOT NULL,result TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS outbox(id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id),event TEXT NOT NULL,at TEXT NOT NULL,channel TEXT NOT NULL DEFAULT 'INTERNAL',status TEXT NOT NULL DEFAULT 'DISABLED',attempts INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS audit(id TEXT PRIMARY KEY,at TEXT NOT NULL,actor TEXT NOT NULL,vendor_id TEXT,event TEXT NOT NULL,data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS inventory_movements(id TEXT PRIMARY KEY,product_id TEXT NOT NULL REFERENCES products(id),at TEXT NOT NULL,actor TEXT NOT NULL,delta INTEGER NOT NULL,reason TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS write_guards(value INTEGER NOT NULL CHECK(value=1));
CREATE TRIGGER IF NOT EXISTS item_vendor_guard BEFORE INSERT ON order_items WHEN NOT EXISTS(SELECT 1 FROM products WHERE id=NEW.product_id AND vendor_id=NEW.vendor_id) BEGIN SELECT RAISE(ABORT,'VENDOR_MISMATCH'); END;
